#define GL_SILENCE_DEPRECATION
#include <OpenGL/OpenGL.h>
#include <OpenGL/gl3.h>
#include <fstream>
#include <iostream>
#include <sstream>
#include <vector>
#include <string>
#include <stdexcept>
#include <regex>
using namespace std;
string readfile(string p){ifstream f(p);if(!f)throw runtime_error(p);return string(istreambuf_iterator<char>(f),{});}
string replaceAll(string s,string a,string b){size_t i=0;while((i=s.find(a,i))!=string::npos){s.replace(i,a.size(),b);i+=b.size();}return s;}
GLuint shader(GLenum type,string s){GLuint id=glCreateShader(type);const char* p=s.c_str();glShaderSource(id,1,&p,nullptr);glCompileShader(id);GLint ok;glGetShaderiv(id,GL_COMPILE_STATUS,&ok);if(!ok){char log[8192];glGetShaderInfoLog(id,sizeof(log),nullptr,log);throw runtime_error(log);}return id;}
GLuint program(string fragment){string v="#version 150\nin vec2 aPosition; out vec2 vTexCoord; void main(){vTexCoord=(aPosition+1.)*.5;gl_Position=vec4(aPosition,0,1);}";fragment=replaceAll(fragment,"precision highp float;","");fragment=replaceAll(fragment,"varying vec2 vTexCoord;","in vec2 vTexCoord; out vec4 outColor;");fragment=replaceAll(fragment,"texture2D(","texture(");fragment=replaceAll(fragment,"gl_FragColor","outColor");GLuint id=glCreateProgram(),vs=shader(GL_VERTEX_SHADER,v),fs=shader(GL_FRAGMENT_SHADER,"#version 150\n"+fragment);glAttachShader(id,vs);glAttachShader(id,fs);glBindAttribLocation(id,0,"aPosition");glLinkProgram(id);GLint ok;glGetProgramiv(id,GL_LINK_STATUS,&ok);if(!ok){char log[8192];glGetProgramInfoLog(id,sizeof(log),nullptr,log);throw runtime_error(log);}glDeleteShader(vs);glDeleteShader(fs);return id;}
struct Buffer{GLuint tex,fbo;int w,h;};
Buffer buffer(int w,int h,bool fp,const void* data=nullptr){Buffer b; b.w=w;b.h=h;glGenTextures(1,&b.tex);glBindTexture(GL_TEXTURE_2D,b.tex);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,fp?GL_NEAREST:GL_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,fp?GL_NEAREST:GL_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);glTexImage2D(GL_TEXTURE_2D,0,fp?GL_RGBA16F:GL_RGBA8,w,h,0,GL_RGBA,fp?GL_HALF_FLOAT:GL_UNSIGNED_BYTE,data);glGenFramebuffers(1,&b.fbo);glBindFramebuffer(GL_FRAMEBUFFER,b.fbo);glFramebufferTexture2D(GL_FRAMEBUFFER,GL_COLOR_ATTACHMENT0,GL_TEXTURE_2D,b.tex,0);if(glCheckFramebufferStatus(GL_FRAMEBUFFER)!=GL_FRAMEBUFFER_COMPLETE)throw runtime_error("Incomplete FBO");return b;}
void draw(GLuint p,Buffer out,vector<GLuint> in,int w,int h){glBindFramebuffer(GL_FRAMEBUFFER,out.fbo);glViewport(0,0,out.w,out.h);glUseProgram(p);glUniform2f(glGetUniformLocation(p,"uStep"),1.f/w,1.f/h);glUniform2f(glGetUniformLocation(p,"uInputSize"),w,h);glUniform1f(glGetUniformLocation(p,"uStrength"),h<1080?.32f:.18f);for(int i=0;i<in.size();i++){glActiveTexture(GL_TEXTURE0+i);glBindTexture(GL_TEXTURE_2D,in[i]);glUniform1i(glGetUniformLocation(p,("u"+to_string(i)).c_str()),i);}glDrawArrays(GL_TRIANGLE_STRIP,0,4);if(glGetError()!=GL_NO_ERROR)throw runtime_error("GPU draw error");}
void save(Buffer b,string file){vector<unsigned char> data(b.w*b.h*4);glBindFramebuffer(GL_FRAMEBUFFER,b.fbo);glReadPixels(0,0,b.w,b.h,GL_RGBA,GL_UNSIGNED_BYTE,data.data());ofstream f(file,ios::binary);f.write((char*)data.data(),data.size());}
void dispose(Buffer b){glDeleteTextures(1,&b.tex);glDeleteFramebuffers(1,&b.fbo);}
int main(int argc,char** argv){try{if(argc!=8)throw runtime_error("assets input.rgba width height outputWidth outputHeight outputPrefix");string root=argv[1],file=argv[2],prefix=argv[7];int w=stoi(argv[3]),h=stoi(argv[4]),ow=stoi(argv[5]),oh=stoi(argv[6]);CGLPixelFormatAttribute attrib[]={kCGLPFAOpenGLProfile,(CGLPixelFormatAttribute)kCGLOGLPVersion_3_2_Core,(CGLPixelFormatAttribute)0};CGLPixelFormatObj pf;GLint n;auto e=CGLChoosePixelFormat(attrib,&pf,&n);if(e||!pf)throw runtime_error("CGL pixel format unavailable");CGLContextObj ctx;e=CGLCreateContext(pf,nullptr,&ctx);CGLDestroyPixelFormat(pf);if(e||!ctx)throw runtime_error("CGL context unavailable");CGLSetCurrentContext(ctx);cout<<"Offline desktop shader validation only: "<<glGetString(GL_RENDERER)<<"\n";GLuint vao,vbo;glGenVertexArrays(1,&vao);glBindVertexArray(vao);glGenBuffers(1,&vbo);glBindBuffer(GL_ARRAY_BUFFER,vbo);float quad[]={-1,-1,1,-1,-1,1,1,1};glBufferData(GL_ARRAY_BUFFER,sizeof(quad),quad,GL_STATIC_DRAW);glVertexAttribPointer(0,2,GL_FLOAT,GL_FALSE,0,0);glEnableVertexAttribArray(0);string raw=readfile(file);if(raw.size()!=w*h*4)throw runtime_error("Bad image size");auto input=buffer(w,h,false,raw.data());auto out=buffer(ow,oh,false);auto copy=program(readfile(root+"/copy.glsl"));auto light=program(readfile(root+"/light.glsl"));draw(copy,out,{input.tex},w,h);save(out,prefix+"-off.rgba");draw(light,out,{input.tex},w,h);save(out,prefix+"-light.rgba");for(string model:{"s","m"}){int count=model=="s"?5:9;vector<Buffer> stages;for(int i=0;i<count;i++){bool last=i==count-1;auto b=buffer(last?w*2:w,last?h*2:h,!last);auto p=program(readfile(root+"/cnn_"+model+"/"+to_string(i)+".glsl"));vector<GLuint> refs;if(i==0)refs={input.tex};else if(last)refs={input.tex,stages.back().tex};else if(model=="m"&&i==7){for(int j=0;j<7;j++)refs.push_back(stages[j].tex);}else refs={stages.back().tex};draw(p,b,refs,w,h);stages.push_back(b);glDeleteProgram(p);}draw(copy,out,{stages.back().tex},w,h);save(out,prefix+"-cnn_"+model+".rgba");for(auto b:stages)dispose(b);cout<<"CNN "<<model<<": "<<count<<" real GPU passes complete\n";}glFinish();dispose(input);dispose(out);glDeleteProgram(copy);glDeleteProgram(light);glDeleteBuffers(1,&vbo);glDeleteVertexArrays(1,&vao);CGLSetCurrentContext(nullptr);CGLDestroyContext(ctx);return 0;}catch(exception& e){cerr<<e.what()<<"\n";return 1;}}
